import subprocess, re, datetime
ADB = "/mnt/c/Users/hzq00/Downloads/platform-tools-latest-windows/platform-tools/adb.exe"
SERIAL = "AVNS023705001888"
PKGS = ["com.hihonor.android.upgradeguide","com.hihonor.magazine","com.hihonor.vmall",
        "cn.honor.qinxuan","com.hihonor.browserhomepage","com.honor.browser","com.hihonor.phoneservice"]
def adb(args, timeout=120):
    r = subprocess.run([ADB, "-s", SERIAL] + args, capture_output=True, text=True, encoding="utf-8", errors="replace", timeout=timeout)
    return r.returncode, r.stdout, r.stderr

raw = {}
meta = {}
for p in PKGS:
    rc, out, err = adb(["shell", "dumpsys", "usagestats", "--user", "0", p])
    raw[p] = out
    meta[p] = {"rc": rc, "err": err[:200]}

# device time ISO
rc, iso, err = adb(["shell", "date", "+%Y-%m-%dT%H:%M:%S%z"])
print("device iso:", iso.strip(), "rc:", rc)

# parse per-bucket fields
bucket_re = re.compile(r'package=(\S+) totalTimeUsed="([^"]*)" lastTimeUsed="([^"]*)" totalTimeVisible="([^"]*)" lastTimeVisible="([^"]*)" lastTimeComponentUsed="([^"]*)" totalTimeFS="([^"]*)" lastTimeFS="([^"]*)" appLaunchCount=(\d+)')
sections = ["In-memory daily stats", "In-memory weekly stats", "In-memory monthly stats", "In-memory yearly stats"]

summary = {}
for p in PKGS:
    out = raw[p]
    b = {}
    for i, sec in enumerate(sections):
        idx = out.find(sec)
        nxt = out.find("In-memory", idx+5) if idx >= 0 else -1
        chunk = out[idx:nxt] if idx >= 0 else ""
        m = bucket_re.search(chunk)
        if m:
            b[sec.replace("In-memory ","").replace(" stats","")] = {
                "totalTimeUsed": m.group(2), "lastTimeUsed": m.group(3),
                "lastTimeVisible": m.group(5), "lastTimeComponentUsed": m.group(6),
                "appLaunchCount": int(m.group(9))}
    summary[p] = b
    print("==", p, "rc:", meta[p]["rc"], "err:", meta[p]["err"] or "-")
    for k, v in b.items():
        print(f"  {k:8s} lastUsed={v['lastTimeUsed']} lastComp={v['lastTimeComponentUsed']} launches={v['appLaunchCount']} totalTime={v['totalTimeUsed']}")

